import (
	"context"
	"testing"
	"time"

	"example.com/remind/store"
)

// Stop may be called more than once (an admin request and shutdown can
// both call it); the second call must not panic.
func TestStopTwice(t *testing.T) {
	d := NewDispatcher(store.New(time.Now), nil, time.Now)
	d.Stop()
	d.Stop()
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	done := make(chan struct{})
	go func() { d.Run(ctx, time.Hour); close(done) }()
	select {
	case <-done:
	case <-time.After(time.Second):
		t.Fatal("Run did not return after Stop")
	}
}
"}

